import SwiftUI
import HealthKit
import WatchConnectivity

@main struct PulseWatchApp: App { var body:some Scene { WindowGroup { WatchHome() } } }
struct WatchHome: View {
    @StateObject private var model=WatchWorkout()
    var body:some View { ScrollView { VStack { Text("MacroPulse").font(.headline); if model.started != nil { TimelineView(.periodic(from:.now,by:1)) { _ in Text(model.clock).font(.title).monospacedDigit() } }; if let rate=model.heartRate { Text("\(Int(rate)) bpm").foregroundStyle(.red) }; Text("\(Int(model.energy)) active kcal"); Text(model.message).font(.caption); if model.active { Button(model.paused ? "Resume":"Pause") { model.toggle() }; Button("Stop & save",role:.destructive) { model.finish() } } else { Button("Start workout") { model.start() } }; Button("+ ¼ jug on phone") { model.command("water",amount:295.735295625) }; Text("Watch workouts are saved to Apple Health. Phone workout controls queue until its app is open; hydration is not double-logged.").font(.caption2) } } }
}
final class WatchWorkout:NSObject,ObservableObject,HKWorkoutSessionDelegate,HKLiveWorkoutBuilderDelegate,WCSessionDelegate {
    @Published var active=false;@Published var paused=false;@Published var started:Date?;@Published var heartRate:Double?;@Published var energy:Double=0;@Published var message="Ready"
    private var pausedAt:Date?;private var pausedSeconds:Double=0;private var endedAt:Date?;private var phoneSession="";var clock:String { let n=Int(max(0,(endedAt ?? pausedAt ?? Date()).timeIntervalSince(started ?? Date())-pausedSeconds));return String(format:"%02d:%02d:%02d",n/3600,n/60%60,n%60) };private let health=HKHealthStore();private var session:HKWorkoutSession?;private var builder:HKLiveWorkoutBuilder?
    override init() { super.init();if WCSession.isSupported() { WCSession.default.delegate=self;WCSession.default.activate() } }
    func start() { let heart=HKObjectType.quantityType(forIdentifier:.heartRate)!,energy=HKObjectType.quantityType(forIdentifier:.activeEnergyBurned)!;health.requestAuthorization(toShare:[HKObjectType.workoutType(),energy],read:[heart,energy]) { success,error in DispatchQueue.main.async { guard success else { self.message=error?.localizedDescription ?? "Health permission request failed";return };do { let config=HKWorkoutConfiguration();config.activityType = .traditionalStrengthTraining;config.locationType = .indoor;let session=try HKWorkoutSession(healthStore:self.health,configuration:config);self.session=session;let builder=session.associatedWorkoutBuilder();self.builder=builder;session.delegate=self;builder.delegate=self;builder.dataSource=HKLiveWorkoutDataSource(healthStore:self.health,workoutConfiguration:config);let now=Date();self.started=now;self.pausedAt=nil;self.pausedSeconds=0;self.endedAt=nil;self.energy=0;self.heartRate=nil;session.startActivity(with:now);builder.beginCollection(withStart:now) { _,error in if let error=error { DispatchQueue.main.async { self.message=error.localizedDescription } } };self.active=true;self.paused=false;self.message="Live watch workout" }catch { self.message=error.localizedDescription } } } }
    func toggle() { if paused { session?.resume();command("resume") } else { session?.pause();command("pause") } }
    func finish() { session?.end();command("stop") }
    func command(_ action:String,amount:Double?=nil) { guard WCSession.default.activationState == .activated else { message="Open the companion phone app to pair first";return };var payload:[String:Any]=["id":UUID().uuidString,"action":action,"date":PulseStore.today,"at":Date().timeIntervalSince1970,"targetSession":phoneSession];if let amount=amount { payload["amount"]=amount };WCSession.default.transferUserInfo(payload) }
    func workoutSession(_ workoutSession:HKWorkoutSession,didChangeTo toState:HKWorkoutSessionState,from fromState:HKWorkoutSessionState,date:Date) { DispatchQueue.main.async { if toState == .paused { self.pausedAt=date };if toState == .running,let paused=self.pausedAt { self.pausedSeconds += date.timeIntervalSince(paused);self.pausedAt=nil };self.paused=toState == .paused;if toState == .ended { self.endedAt=date };if toState == .ended { self.builder?.endCollection(withEnd:date) { _,error in self.builder?.finishWorkout { _,finishError in DispatchQueue.main.async { self.active=false;self.message=(finishError ?? error)?.localizedDescription ?? "Workout saved to Apple Health" } } } } } }
    func workoutSession(_ workoutSession:HKWorkoutSession,didFailWithError error:Error) { DispatchQueue.main.async { self.active=false;self.message=error.localizedDescription } }
    func workoutBuilderDidCollectEvent(_ workoutBuilder:HKLiveWorkoutBuilder) {}
    func workoutBuilder(_ workoutBuilder:HKLiveWorkoutBuilder,didCollectDataOf collectedTypes:Set<HKSampleType>) { for type in collectedTypes { guard let q=type as? HKQuantityType,let stats=workoutBuilder.statistics(for:q) else { continue };if q.identifier==HKQuantityTypeIdentifier.heartRate.rawValue { let value=stats.mostRecentQuantity()?.doubleValue(for:HKUnit.count().unitDivided(by:.minute()));DispatchQueue.main.async { self.heartRate=value } };if q.identifier==HKQuantityTypeIdentifier.activeEnergyBurned.rawValue { let value=stats.sumQuantity()?.doubleValue(for:.kilocalorie()) ?? 0;DispatchQueue.main.async { self.energy=value } } } }
    func session(_ session:WCSession,activationDidCompleteWith activationState:WCSessionActivationState,error:Error?) { if let snapshot=session.receivedApplicationContext["snapshot"] as? [String:Any] { DispatchQueue.main.async { self.phoneSession=snapshot["sessionID"] as? String ?? "" } } }
    func session(_ session:WCSession,didReceiveApplicationContext applicationContext:[String:Any]) { if let snapshot=applicationContext["snapshot"] as? [String:Any] { DispatchQueue.main.async { self.phoneSession=snapshot["sessionID"] as? String ?? "" } } }
}
